": "fragmentation-of-hungary", "targetName": "Fragmentation of Hungary", "context": "John Zápolya's disputed succession and alliance with the Ottomans ultimately led to the tri-partition of the Kingdom of Hungary after his death in 1540."}, {"sourceSlug": "ferdinand-i-holy-roman-emperor", "sourceName": "Ferdinand I, Holy Roman Emperor", "verb": "COLLABORATES_WITH", "targetSlug": "hapsburg-monarchy", "targetName": "Habsburg Monarchy", "context": "Ferdinand I, through his claim to the Hungarian throne and subsequent conflict with Zápolya, actively worked to integrate Hungary into the expanding Habsburg Monarchy."}]}, {"timestamp": "2026-10-28T13:34:57Z", "editorId": "gemini-2.5-flash·cloud·GH#40694073292", "field": "detailsJson.places", "oldValue": [{"name": "Spiš Castle", "role": "Birth place"}], "newValue": [{"name": "Buda, Kingdom of Hungary", "role": "Royal capital"}, {"name": "Székesfehérvár, Kingdom of Hungary", "role": "Coronation site"}, {"name": "Transylvania, Kingdom of Hungary", "role": "Voivode's domain"}]}, {"timestamp": "2026-10-28T13:34:57Z", "editorId": "gemini-2.5-flash·cloud·GH#40694073292", "field": "subjects", "oldValue": ["Monarchs & Rulers"], "newValue": ["Hungary", "Transylvania", "Ottoman Empire", "Habsburg Monarchy", "Monarchy", "Dynastic Succession", "Military History", "Early Modern Europe", "Central Europe"]}, {"timestamp": "2026-10-28T13:34:57Z", "editorId": "gemini-2.5-flash·cloud·GH#40694073292", "field": "frameworks", "oldValue": ["POLITICAL_SYSTEMS", "EMPIRE_AND_COLONIALISM", "GEOPOLITICAL_LINKAGE", "TEMPORAL_LINKAGE"], "newValue": ["DIPLOMATIC_HISTORY", "STRUCTURAL_ANALYSIS", "WORLD_SYSTEMS"]}], "_unsyncedEdits": true}
